-- Split the /near "Other places" group (attractions with no category) into four new categories and
-- hide what isn't a thing to do. Approved per place from scripts/output/other-places-proposal.json.
-- Uses the overrides from 20261121050029_attraction_overrides, so it survives a re-import.
--
-- New category keys (the page slugs are set in the app):
--   art_gallery     Art galleries and studios
--   cinema_theater  Cinemas, theaters and live music
--   bowling_games   Bowling and games
--   casino          Casinos and gaming
-- Hidden: restaurants and bars, shops, and one-person studios with 3 or fewer reviews.
-- Rows that already had an override (e.g. a display name) keep it; hidden and category are added.
-- To undo: delete from maryland_attraction_overrides where source = 'near-other-split-2026-11'
-- (and strip the appended reason on merged rows), then apply_attraction_overrides().

) as v(place_id, hidden, category, reason)
on conflict (place_id) do update
set hidden = o.hidden or excluded.hidden,
    category = coalesce(excluded.category, o.category),
    reason = o.reason || '; ' || excluded.reason;

update public.maryland_attraction_overrides o
set previous_category = a.category,
    previous_duplicate_of = a.duplicate_of,
    previous_is_pseo_eligible = a.is_pseo_eligible
from public.maryland_attractions a
where a.place_id = o.place_id and o.previous_is_pseo_eligible is null;

select public.apply_attraction_overrides();
select public.refresh_attraction_breweries();
